{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-tabs.json
    Features behind a tab list: the chosen tab shows its text and a picture. The page keeps the chosen tab (`active`, empty for the first) and updates it on the `select` event. Axes: panel (split: text beside the picture, stack: picture below), tone, density.
    Props (p): id, title, features, tabsLabel, active, panel, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_features = ($p['features'] ?? null)}
{var $v_tabsLabel = ($p['tabsLabel'] ?? null)}
{var $v_active = ($p['active'] ?? '')}
{var $v_panel = ($p['panel'] ?? 'split')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {capture $c_7}
    {capture $c_2}
      {foreach ui_l($v_features) as $v_f}
        {var $v_i = $iterator->counter0}
        {capture $c_1}
          {=ui_text(ui_get($v_f, ['title']))}
        {/capture}
        {=ui_include('blocks/switcher-item.latte', ['p' => ['active' => ui_or([ui_eq(ui_get($v_f, ['id']), $v_active), ui_and([ui_eq($v_active, ''), ui_eq($v_i, 0)])])], 'children' => $c_1])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('blocks/switcher.latte', ['p' => ['label' => $v_tabsLabel, 'className' => ui_cnv(['w-fit max-w-full flex-wrap'])], 'children' => $c_2])|noescape}
    {foreach ui_l($v_features) as $v_f}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_or([ui_eq(ui_get($v_f, ['id']), $v_active), ui_and([ui_eq($v_active, ''), ui_eq($v_i, 0)])]))}
        {capture $c_6}
          {capture $c_5}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_f, ['icon'])), 'Size' => 24]])|noescape}
            {capture $c_3}
              {=ui_text(ui_get($v_f, ['title']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => '2xl', 'Weight' => 'bold'], 'children' => $c_3])|noescape}
            {capture $c_4}
              {=ui_text(ui_get($v_f, ['text']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Class' => 'text-muted-foreground'], 'children' => $c_4])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4'], 'children' => $c_5])|noescape}
          {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_f, ['title']), 'ratio' => '4/3']])|noescape}
        {/capture}
        {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_panel, 'split')) ? '1-2' : '1')), 'Class' => 'items-center gap-8', 'Attrs' => ui_attrs(['data-testid', 'tab-panel', 'role', 'tabpanel'])], 'children' => $c_6])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '6', 'Align' => 'stretch'], 'children' => $c_7])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_8])|noescape}
